import java.util.*;

class Solution {
  public int countSubMultisets(List<Integer> nums, int l, int r) {
    final int MOD = 1_000_000_007;
    int[] freq = new int[r + 1];
    for (int x : nums) if (x <= r) freq[x]++;
    long[] dp = new long[r + 1];
    dp[0] = 1;
    for (int value = 1; value <= r; value++)
      if (freq[value] > 0) {
        long[] next = new long[r + 1];
        for (int rem = 0; rem < value; rem++) {
          long window = 0;
          for (int sum = rem; sum <= r; sum += value) {
            window = (window + dp[sum]) % MOD;
            int old = sum - (freq[value] + 1) * value;
            if (old >= 0) window = (window - dp[old] + MOD) % MOD;
            next[sum] = window;
          }
        }
        dp = next;
      }
    long answer = 0;
    for (int sum = l; sum <= r; sum++) answer = (answer + dp[sum]) % MOD;
    return (int) (answer * (freq[0] + 1L) % MOD);
  }
}
